// Swift-concurrency sketch (illustrative)
actor AnnotationQueue {
  private var queue: [ImageTask] = []
  func enqueue(_ t: ImageTask) { queue.append(t) }
  func run() async {
    for await task in tasks() {
      // process
    }
  }
}
```

